changeSet.sql:
create index if not exists idx_catalog_dataset_lineage_validity
    on catalog_dataset_lineage (valid_from, valid_to);
create index if not exists idx_catalog_dataset_lineage_up_validity
    on catalog_dataset_lineage (upstream_dataset_id, valid_from);
create index if not exists idx_catalog_dataset_lineage_down_validity
    on catalog_dataset_lineage (downstream_dataset_id, valid_from);
